INSERT INTO public.home_sections (key,label,eyebrow,heading,subheading,body,cta_label,cta_href,sort_order,extra) VALUES
('hero','Hero','AMARC Engineering & Construction','We build what Pakistan runs on.','From foundation to finishing — design, engineering and delivery under one roof.','Twenty years of turnkey construction across Punjab and Sindh, delivered to international standards and audited at every phase.','Start a project','/contact',1,'{"secondary_label":"See our work","secondary_href":"/projects"}'::jsonb),
('credibility','Credibility strip',NULL,NULL,NULL,NULL,NULL,NULL,2,'{"items":[{"value":"2004","label":"Established"},{"value":"PEC C-A","label":"Licence category"},{"value":"ISO 9001","label":"Certified"},{"value":"3","label":"Regional offices"}]}'::jsonb),
('stats','Stats counters','By the numbers','A record you can audit.','Every figure below is drawn from projects listed in our portfolio.',NULL,NULL,NULL,3,'{"items":[{"value":184,"suffix":"","label":"Projects completed"},{"value":23,"suffix":"","label":"Currently ongoing"},{"value":6.4,"suffix":"M","label":"Sq. ft. delivered"},{"value":41500,"suffix":"M","prefix":"PKR ","label":"Contract value executed"}]}'::jsonb),
('services','Services','What we do','Nine disciplines. One accountable team.','Design, engineering, procurement and construction handled in-house so nothing falls between consultants.',NULL,'View all services','/services',4,'{}'::jsonb),
('sectors','Sectors','Where we build','Sectors we know inside out.','Each sector has its own approvals, standards and risk profile. We staff accordingly.',NULL,NULL,'/projects',5,'{}'::jsonb),
('projects','Featured projects','Portfolio','Recently delivered.','A selection of completed and ongoing work across Pakistan.',NULL,'Browse all projects','/projects',6,'{}'::jsonb),
('process','Process','How we work','Six phases. No surprises.','Every project runs through the same audited sequence, with a written sign-off gate between each phase.',NULL,NULL,NULL,7,'{"steps":[{"title":"Feasibility & survey","body":"Topography, soil investigation, zoning and a costed feasibility report before anything is drawn."},{"title":"Design & engineering","body":"Architectural concept, structural analysis and MEP coordination issued as a single stamped set."},{"title":"Approvals & tendering","body":"LDA / SBCA / CDA submissions, NOC tracking, BOQ preparation and subcontractor tendering."},{"title":"Construction","body":"Self-performed civil works with directly employed site engineers and daily progress reporting."},{"title":"QA/QC & HSE","body":"Third-party material testing, weekly safety audits and a documented non-conformance register."},{"title":"Handover & O&M","body":"As-built drawings, snag closure, warranty pack and a twelve-month defects liability period."}]}'::jsonb),
('developments','Developments','Real estate','Newly launched developments.','Our own developments, built and sold by the same team that designs them.',NULL,'View developments','/real-estate',8,'{}'::jsonb),
('clients','Clients','Trusted by','Clients and partners.',NULL,NULL,NULL,NULL,9,'{}'::jsonb),
('certifications','Certifications','Compliance','Licensed, certified, insured.','Registration and certification details are available for download or verification on request.',NULL,'View certifications','/about/certifications',10,'{}'::jsonb),
('testimonials','Testimonials','References','What clients say.',NULL,NULL,NULL,NULL,11,'{}'::jsonb),
('insights','Insights','Insights','From the site office.','Practical notes on construction cost, regulation and method in Pakistan.',NULL,'Read all insights','/insights',12,'{}'::jsonb),
('cta','Contact CTA','Get in touch','Tell us what you want to build.','Send us the plot details and a rough brief. You will get a written response within two working days.',NULL,'Request a quote','/contact',13,'{}'::jsonb)
INSERT INTO public.services (slug,title,short_title,icon,summary,description,bullets,process_steps,faqs,sort_order) VALUES
('architectural-design','Architectural Design','Architecture','DraftingCompass','Concept to construction drawings for residential, commercial and institutional buildings.','Our architecture studio takes a project from massing study through to a stamped construction set. We work in Revit, coordinate live with the structural and MEP teams in the same office, and issue a single reconciled drawing package — which is why our sites see far fewer RFIs than the industry norm. Every scheme is tested against local by-laws (LDA, SBCA, CDA, RDA) before a single sheet is issued.','["Concept design and massing studies","3D visualisation and walkthroughs","Working drawings and detail sheets","By-law compliance and authority submission","Material and finishes schedules","Coordination with structural and MEP"]'::jsonb,'["Brief and site appraisal","Concept and options","Design development","Authority submission","Construction documentation"]'::jsonb,'[{"q":"Do you work on plots outside Lahore?","a":"Yes. We regularly deliver architectural packages in Karachi, Islamabad, Rawalpindi, Faisalabad and Multan, and we handle the relevant local authority submissions in each."},{"q":"How long does a house design take?","a":"A typical 1-kanal residence takes six to eight weeks from brief to a full construction set, including one round of authority comments."}]'::jsonb,1),
('structural-design','Structural Design','Structural','Frame','RCC and steel design, seismic analysis and independent structural vetting.','We design reinforced concrete and structural steel frames for buildings up to twenty storeys, plus retaining structures, water-retaining works and industrial foundations. Analysis is carried out in ETABS and SAFE against the Building Code of Pakistan (Seismic Provisions), with peer-reviewed calculations issued alongside every drawing set. We also provide independent structural vetting for clients who want a second opinion on someone else''s design.','["RCC frame and slab design","Structural steel and pre-engineered buildings","Seismic analysis to BCP-SP 2007","Raft, pile and mat foundation design","Retaining walls and basements","Independent third-party vetting"]'::jsonb,'["Load assessment","Analysis modelling","Member design","Detailing and BBS","Peer review and stamping"]'::jsonb,'[{"q":"Do you issue stamped drawings?","a":"Yes — all structural drawings are stamped by a PEC-registered professional engineer."},{"q":"Can you review a design done by another firm?","a":"We do independent vetting regularly, and issue a written report with a clear pass, conditional or fail verdict."}]'::jsonb,2),
('construction-services','Construction Services','Construction','HardHat','Turnkey grey structure and finishing, self-performed with directly employed site teams.','This is the core of the business. We take projects on a turnkey basis — grey structure, finishes, external works and handover — with directly employed site engineers, foremen and QA staff rather than a chain of labour contractors. Clients get a single point of accountability, a weekly progress report with photographs, and a cost position reconciled against the BOQ every month.','["Turnkey grey structure","Complete finishing works","Renovation and vertical extensions","Industrial sheds and warehousing","External development and hardscape","Monthly cost reconciliation"]'::jsonb,'["Mobilisation and site setup","Substructure","Superstructure","Finishes and MEP","Snagging and handover"]'::jsonb,'[{"q":"Do you work on a cost-plus or fixed-price basis?","a":"Both. Most private residential clients prefer fixed-price against a frozen BOQ; institutional clients usually go cost-plus with an agreed management fee."},{"q":"What is the defects liability period?","a":"Twelve months from practical completion as standard, extendable by agreement."}]'::jsonb,3),
('project-management','Project Management','PM','GanttChartSquare','Client-side project management, cost control and construction supervision.','When you already have a contractor, we act for you. Our PM teams run the programme, verify interim payment certificates, chase the approvals, hold the design consultants to their deliverable dates and maintain a live risk register. Clients typically bring us in when a project has slipped or when the value is high enough that independent oversight pays for itself.','["Programme development and tracking","Interim payment certification","Contractor performance monitoring","Change and variation control","Risk register and mitigation","Monthly client reporting"]'::jsonb,'["Baseline programme","Weekly site supervision","Monthly valuation","Variation control","Completion and closeout"]'::jsonb,'[]'::jsonb,4),
('real-estate','Real Estate','Real Estate','Building2','Development, sales and advisory on our own and third-party projects.','Our real estate arm develops residential and mixed-use projects, and advises landowners on the highest-value use for a site. Because the construction team sits in the same building, our feasibility numbers are built from real, current construction rates rather than market averages — which is why our launches hold their delivery dates.','["Land acquisition advisory","Highest-and-best-use studies","Development feasibility and cash-flow modelling","Project launch and sales","Booking and instalment administration","Possession and transfer support"]'::jsonb,'["Site appraisal","Feasibility","Approvals","Launch","Delivery and possession"]'::jsonb,'[{"q":"Do you offer instalment plans?","a":"Yes — most of our developments run on a 36 to 48 month instalment structure with a booking amount, monthly instalments and balloon payments. Full schedules are published on each development page."}]'::jsonb,5),
('material-supplies','Material Supplies','Materials','PackageCheck','Bulk supply of steel, cement, aggregate, block and finishing materials.','We buy at project scale and pass the rate on. Our supply division stocks and delivers deformed steel bar, cement, crush and sand, concrete block, tiles and sanitary ware across Punjab, with mill test certificates supplied on every steel consignment and third-party cube testing available for ready-mix.','["Deformed steel bar with mill certificates","Cement — all major brands","Crush, sand and aggregate","Concrete block and paver","Tiles, sanitary and fittings","Site delivery and unloading"]'::jsonb,'[]'::jsonb,'[]'::jsonb,6),
('contracts-consultancy','Contracts & Consultancy','Contracts','Scale','Contract drafting, claims, BOQ preparation and dispute resolution.','Construction disputes in Pakistan are almost always documentation failures. We draft and review construction contracts, prepare and vet bills of quantity, assemble and defend claims, and act as an expert in arbitration. Our team works to FIDIC and PEC standard forms and has appeared before arbitral tribunals in Lahore and Karachi.','["Contract drafting and review","BOQ preparation and vetting","Rate analysis and market comparison","Claim preparation and defence","Extension-of-time analysis","Arbitration and expert testimony"]'::jsonb,'[]'::jsonb,'[]'::jsonb,7),
('topography-soil-testing','Topography & Soil Testing','Survey & Soil','Mountain','Total-station survey, contour mapping, SPT boreholes and lab soil classification.','Every project we touch starts here. Our survey crew produces total-station topographic surveys and contour plans, and our geotechnical team carries out standard penetration test boreholes with laboratory classification, bearing capacity determination and settlement analysis. Reports are issued in a format accepted by every major approving authority in Pakistan.','["Total-station topographic survey","Contour and level plans","Plot demarcation","SPT boreholes to 30m","Laboratory soil classification","Bearing capacity and settlement report"]'::jsonb,'[]'::jsonb,'[{"q":"How deep do you bore?","a":"Standard practice is three boreholes to 15 metres for a low-rise building and up to 30 metres for high-rise or heavy industrial loads."}]'::jsonb,8),
('interior-design','Interior Design','Interiors','Sofa','Interior architecture, joinery detailing and fit-out execution.','We design and build interiors — residential, corporate office, retail and hospitality. The studio produces full joinery and services detailing rather than mood boards, and the same fit-out team that priced the job executes it, so what gets specified is what gets installed.','["Space planning and interior architecture","Joinery and millwork detailing","Lighting and electrical layouts","FF&E specification and procurement","Turnkey fit-out execution","Corporate and retail rollouts"]'::jsonb,'[]'::jsonb,'[]'::jsonb,9)
INSERT INTO public.sectors (slug,title,icon,summary,description,sort_order) VALUES
('residential','Residential','Home','Houses, apartments and gated housing schemes.','From single-kanal residences in DHA to multi-storey apartment blocks, residential is where AMARC started and still delivers the highest volume of work.',1),
('commercial','Commercial','Store','Offices, retail, plazas and mixed-use.','Commercial work demands speed to revenue. We programme these projects backwards from the tenant handover date.',2),
('industrial','Industrial','Factory','Factories, warehouses, cold stores and process plant civils.','Industrial clients need production uptime. We build around live operations and phase works to keep the plant running.',3),
('infrastructure','Infrastructure','Route','Roads, drainage, water supply and site development.','Public and private infrastructure — carriageways, storm drainage, sewerage and bulk earthworks.',4),
('healthcare','Healthcare','HeartPulse','Hospitals, clinics and diagnostic facilities.','Healthcare construction is governed by infection control, medical gas and redundancy requirements that ordinary contractors miss.',5),
('education','Education','GraduationCap','Schools, colleges and campus buildings.','Campus work runs on the academic calendar. We build to summer-break windows.',6),
('hospitality','Hospitality','UtensilsCrossed','Hotels, restaurants and banquet facilities.','Finish quality is the whole product in hospitality. These projects get our senior fit-out teams.',7),
('institutional','Institutional','Landmark','Government, banking and community buildings.','Institutional projects carry heavy documentation and audit requirements. Our contracts team handles them.',8)
INSERT INTO public.projects (slug,title,client,city,location,sector_slug,status,value_pkr_millions,covered_area,plot_area,storeys,start_date,completion_date,architect,summary,description,scope,is_featured,sort_order) VALUES
('gulberg-corporate-tower','Gulberg Corporate Tower','Meridian Holdings (Pvt) Ltd','Lahore','Main Boulevard, Gulberg III','commercial','completed',1840,'214,000 sq ft','2 kanal','B+G+14','2020-03-01','2023-08-15','AMARC Architecture Studio','A fourteen-storey grade-A office tower with two basement levels, delivered on a fixed-price turnkey contract.','Gulberg Corporate Tower is a B+G+14 commercial building on Main Boulevard with 214,000 sq ft of leasable area, two basement parking levels and a double-height entrance atrium. The structural frame is a post-tensioned flat slab on a raft foundation, which cut the floor-to-floor height by 300mm across fourteen levels and gained the client an additional half floor within the approved height envelope. The project was delivered nine weeks ahead of the contractual completion date.','["Feasibility","Architectural Design","Structural Design","Construction","Project Management"]'::jsonb,true,1),
('dha-phase-8-residence','DHA Phase 8 Private Residence','Private client','Lahore','Block Z, DHA Phase 8','residential','completed',96,'11,400 sq ft','2 kanal','B+G+1','2022-01-10','2023-06-30','AMARC Architecture Studio','A two-kanal contemporary residence with basement, home cinema and landscaped courtyard.','A two-kanal family residence built around a central courtyard, with a full basement housing a home cinema, gymnasium and staff quarters. The elevation uses sandblasted Badal grey stone and exposed board-marked concrete. Interiors, joinery and landscaping were all executed in-house.','["Architectural Design","Structural Design","Construction","Interior Design"]'::jsonb,true,2),
('sundar-industrial-facility','Sundar Industrial Estate Manufacturing Facility','Zafar Textiles Ltd','Lahore','Sundar Industrial Estate','industrial','completed',720,'168,000 sq ft','12 acres','G+1','2019-06-01','2021-02-20','AMARC Architecture Studio','A 168,000 sq ft pre-engineered manufacturing shed with allied civil works and utility block.','A textile manufacturing facility comprising a 168,000 sq ft pre-engineered steel shed on isolated pad foundations, a two-storey RCC administration and utility block, effluent treatment civils, internal roads and a 400kVA substation building. Machine foundations were designed for dynamic loads with isolation pads to keep vibration within tolerance for the ring-frame line.','["Topography & Soil Testing","Structural Design","Construction","Material Supplies"]'::jsonb,true,3),
('bahria-town-apartments','Meadow Court Apartments','Sarwar Developers','Rawalpindi','Bahria Town Phase 7','residential','ongoing',1310,'186,000 sq ft','4 kanal','G+9','2024-04-01','2026-11-30','Studio Kohsar','A 96-unit residential apartment building currently at ninth-floor slab stage.','Meadow Court is a G+9 residential building of 96 apartments in one, two and three-bedroom configurations, with a podium car park, rooftop community deck and standby generation for full-load backup. The project is currently at ninth-floor slab casting with finishing works underway on the lower six floors.','["Structural Design","Construction","Project Management"]'::jsonb,true,4),
('karachi-diagnostic-centre','Shahrah-e-Faisal Diagnostic Centre','Aafiyat Health Network','Karachi','Shahrah-e-Faisal','healthcare','completed',465,'52,000 sq ft','1,100 sq yd','G+5','2021-09-15','2023-04-10','Arif Hasan Associates','A six-level diagnostic and day-care hospital with MRI vault and medical gas reticulation.','A 52,000 sq ft diagnostic facility with radiology, pathology, day-care surgery and consulting floors. The scope included a lead-lined MRI vault with a non-ferrous structural zone, full medical gas reticulation with manifold room, HEPA-filtered air handling to the procedure suites and N+1 redundant power. Commissioned and handed over with all statutory health approvals in place.','["Structural Design","Construction","Project Management","Interior Design"]'::jsonb,true,5),
('johar-town-retail-plaza','Johar Town Retail Plaza','Bilal Estate Holdings','Lahore','Block G1, Johar Town','commercial','completed',380,'46,000 sq ft','1 kanal','B+G+5','2021-02-01','2022-10-05','AMARC Architecture Studio','A six-level retail and office plaza with basement parking, delivered in twenty months.','A mixed retail and office plaza with basement parking, ground and first-floor retail and four office floors above. A glass curtain wall to the boulevard elevation with an aluminium fin screen provides shading on the west face and cut the cooling load by an estimated eighteen per cent.','["Architectural Design","Structural Design","Construction"]'::jsonb,false,6),
('faisalabad-cold-store','Faisalabad Cold Storage Complex','Punjab Agro Foods','Faisalabad','Sargodha Road','industrial','completed',540,'88,000 sq ft','6 acres','G+1','2020-08-01','2022-03-18','AMARC Architecture Studio','An 8,000-tonne controlled-atmosphere cold storage facility with insulated panel envelope.','An 8,000-tonne capacity cold storage complex with twelve controlled-atmosphere chambers, insulated sandwich panel envelope, vapour-sealed floor slab with under-slab heating to prevent frost heave, dock levellers and an ammonia plant room built to the required separation standards.','["Topography & Soil Testing","Structural Design","Construction"]'::jsonb,false,7),
('multan-campus-block','Government College Campus Block','Higher Education Department, Punjab','Multan','Bosan Road','education','completed',298,'64,000 sq ft','4 acres','G+2','2019-03-01','2020-12-22','Nespak (design) / AMARC (build)','A three-storey academic block of twenty-four classrooms and four laboratories.','A three-storey academic block delivered under a Punjab HED contract, containing twenty-four classrooms, four science laboratories, a library and staff facilities. Built to PWD specification with third-party material testing on every concrete pour and a full documentation trail for departmental audit.','["Construction","Contracts & Consultancy"]'::jsonb,false,8),
('ravi-road-widening','Ravi Road Carriageway & Drainage','Lahore Development Authority','Lahore','Ravi Road','infrastructure','completed',412,'3.2 km','—','—','2018-11-01','2020-05-30',NULL,'Dual carriageway widening with box culvert storm drainage over a 3.2 km stretch.','Widening of 3.2 km of Ravi Road to dual two-lane carriageway, including subgrade improvement, wet-mix macadam base, asphaltic wearing course, RCC box culvert storm drainage, kerbing, footpath and street lighting. Traffic was maintained throughout via a phased half-width construction sequence.','["Topography & Soil Testing","Construction","Project Management"]'::jsonb,false,9),
('islamabad-boutique-hotel','Blue Area Boutique Hotel','Serena Hospitality Ventures','Islamabad','Jinnah Avenue, Blue Area','hospitality','ongoing',890,'71,000 sq ft','2,000 sq yd','B+G+7','2025-01-15','2027-03-31','Studio Kohsar','A 64-key boutique hotel with rooftop restaurant, currently in structural phase.','A 64-key boutique hotel comprising a basement plant and parking level, ground-floor lobby and restaurant, six guest floors and a rooftop dining terrace with views to the Margalla Hills. Structure is a shear-wall core with post-tensioned floor plates. Currently at fifth-floor slab.','["Architectural Design","Structural Design","Construction","Interior Design"]'::jsonb,false,10),
('dha-karachi-villas','Creek Vista Villas','Habib Land (Pvt) Ltd','Karachi','DHA Phase 8, Karachi','residential','handed_over',1120,'148,000 sq ft','9 acres','G+1','2018-05-01','2021-09-15','AMARC Architecture Studio','Thirty-two detached villas with shared amenity and full external development.','A gated cluster of thirty-two detached villas of 4,600 sq ft each, with shared clubhouse, pool, internal roads, underground utilities and perimeter security infrastructure. Delivered in three phases so early buyers could take possession ahead of full scheme completion.','["Architectural Design","Structural Design","Construction","Real Estate"]'::jsonb,false,11),
('lahore-bank-rollout','Regional Bank Branch Rollout','Askari Commercial Group','Lahore','14 branches, Punjab','institutional','ongoing',186,'38,000 sq ft','—','—','2025-06-01','2026-09-30','AMARC Interior Studio','A fourteen-branch interior fit-out rollout on a rolling four-week-per-branch programme.','A rolling fit-out programme across fourteen retail bank branches in Punjab, each delivered to an identical brand specification on a four-week site window. Scope covers demolition, partitioning, joinery, strong-room civils, ELV, HVAC modification and signage. Nine branches are complete and operational.','["Interior Design","Construction","Project Management"]'::jsonb,false,12)
INSERT INTO public.developments (slug,title,city,location,status,summary,description,storeys,handover,starting_price,amenities,highlights,unit_types,payment_plan,is_featured,sort_order) VALUES
('amarc-vantage','AMARC Vantage','Lahore','Main Boulevard, Gulberg III','newly_launched','Twenty-two storeys of serviced apartments and offices on Main Boulevard.','AMARC Vantage is our flagship development: a B2+G+22 mixed-use tower on Main Boulevard, Gulberg III, combining four retail levels, eight office floors and ten floors of fully serviced residential apartments. Designed, engineered and built entirely in-house, with a committed handover date backed by a liquidated damages clause in every buyer agreement.','B2+G+22','Q4 2029','PKR 24,500,000','["24/7 security and CCTV","Full-load standby power","High-speed lifts (4 nos.)","Rooftop infinity pool","Residents gymnasium","Two basement parking levels","Concierge and facility management","Fibre-optic connectivity"]'::jsonb,'["Main Boulevard frontage","Delivered by the contractor, not a middleman","Liquidated damages on late handover","Escrowed buyer payments"]'::jsonb,'[{"type":"Studio Apartment","area":"620 sq ft","price":"PKR 24,500,000"},{"type":"1 Bedroom","area":"940 sq ft","price":"PKR 36,200,000"},{"type":"2 Bedroom","area":"1,480 sq ft","price":"PKR 55,800,000"},{"type":"3 Bedroom","area":"2,150 sq ft","price":"PKR 79,400,000"},{"type":"Office Floor Plate","area":"4,200 sq ft","price":"On request"}]'::jsonb,'[{"milestone":"Booking","percent":"15%","note":"On agreement signing"},{"milestone":"Confirmation","percent":"10%","note":"Within 60 days"},{"milestone":"Monthly instalments","percent":"45%","note":"48 equal monthly instalments"},{"milestone":"Half-yearly balloons","percent":"20%","note":"8 balloon payments"},{"milestone":"On possession","percent":"10%","note":"At handover"}]'::jsonb,true,1),
('amarc-courtyard-homes','AMARC Courtyard Homes','Lahore','Sector M, DHA Phase 9 Prism','ongoing','Forty-eight courtyard houses on 10-marla and 1-kanal plots.','A gated cluster of forty-eight courtyard houses in DHA Phase 9 Prism, offered on 10-marla and 1-kanal plots. Each house is built around a private central courtyard that brings daylight into the core of the plan — a response to the deep, narrow plot geometry that makes most DHA houses dark in the middle. Grey structure is complete on the first twenty units.','G+1','Q2 2028','PKR 41,000,000','["Gated community with single entry","Underground utilities","Community park and play area","Mosque within cluster","Wide 40ft internal roads","Piped natural gas"]'::jsonb,'["Courtyard-centred plan","Built and sold by the same team","Structural warranty of ten years"]'::jsonb,'[{"type":"10 Marla Courtyard House","area":"3,400 sq ft","price":"PKR 41,000,000"},{"type":"1 Kanal Courtyard House","area":"5,800 sq ft","price":"PKR 72,500,000"}]'::jsonb,'[{"milestone":"Booking","percent":"20%","note":"On agreement signing"},{"milestone":"Monthly instalments","percent":"50%","note":"36 equal monthly instalments"},{"milestone":"Balloon payments","percent":"20%","note":"6 half-yearly balloons"},{"milestone":"On possession","percent":"10%","note":"At handover"}]'::jsonb,true,2),
('amarc-trade-centre','AMARC Trade Centre','Faisalabad','Susan Road','newly_launched','Retail and wholesale trade floors with dedicated loading and cold rooms.','A purpose-built trade centre on Susan Road offering retail shops on the lower two floors and wholesale trade units above, with a dedicated rear loading dock, freight lift, and cold-room provision for perishable traders. Designed for the way Faisalabad wholesale trade actually operates rather than as a generic shopping plaza.','G+5','Q1 2029','PKR 8,900,000','["Dedicated freight lift","Rear loading dock","Cold room provision","Standby power","Fire detection and suppression","Prayer area and washrooms per floor"]'::jsonb,'["Purpose-built for wholesale trade","Loading separated from customer access"]'::jsonb,'[{"type":"Ground Floor Shop","area":"280 sq ft","price":"PKR 14,600,000"},{"type":"First Floor Shop","area":"320 sq ft","price":"PKR 10,200,000"},{"type":"Trade Unit","area":"640 sq ft","price":"PKR 8,900,000"}]'::jsonb,'[{"milestone":"Booking","percent":"25%","note":"On agreement signing"},{"milestone":"Monthly instalments","percent":"55%","note":"40 equal monthly instalments"},{"milestone":"On possession","percent":"20%","note":"At handover"}]'::jsonb,false,3)
INSERT INTO public.team_members (name,role,credentials,bio,sort_order) VALUES
('Arshad Mahmood','Founder & Chief Executive','B.Sc. Civil Engineering (UET Lahore), PEC Registered','Founded AMARC in 2004 after eleven years on site with a national contractor. Still reviews every project over PKR 500 million personally.',1),
('Ayesha Rauf','Director, Architecture','B.Arch (NCA Lahore), PCATP Registered','Leads the architecture studio. Twenty years across residential, commercial and healthcare, with a particular interest in passive cooling for Punjab climate.',2),
('Bilal Cheema','Director, Structural Engineering','M.Sc. Structural Engineering (UET Taxila), PEC Registered','Runs structural design and independent vetting. Has stamped over four hundred building designs and appeared as a structural expert in arbitration.',3),
('Nadia Sultan','Head of Contracts & Commercial','LL.B, MRICS','Handles contract drafting, claims and commercial control. Previously with a FIDIC-based consultancy in Dubai.',4),
('Omer Farooq','Head of Construction','B.Sc. Civil Engineering (UET Lahore), NEBOSH IGC','Responsible for all site delivery and HSE across active projects. Eighteen years of self-performed construction experience.',5),
('Hina Javed','Head of Real Estate','MBA (LUMS)','Leads development feasibility, launches and buyer relations for AMARC own developments.',6);
INSERT INTO public.testimonials (author,author_role,company,quote,rating,sort_order) VALUES
('Kamran Sheikh','Managing Director','Meridian Holdings (Pvt) Ltd','They handed over the Gulberg tower nine weeks early on a fixed price, and the monthly cost reports were accurate enough that we never had a surprise. I have not had that experience with any other contractor in Lahore.',5,1),
('Dr. Faisal Aziz','Chief Executive','Aafiyat Health Network','Hospital construction is unforgiving — the medical gas, the MRI vault, the redundancy. AMARC understood all of it without us having to bring in a specialist consultant from abroad.',5,2),
('Zafar Iqbal','Chairman','Zafar Textiles Ltd','They built our Sundar plant around a live production schedule and never once shut us down. The machine foundations were spot on.',5,3),
('Saira Ahmed','Private client','DHA Phase 8, Lahore','The house came out exactly as the drawings promised, which sounds like it should be normal and in Pakistan is not. The joinery in particular is beautiful.',5,4),
('Tariq Sarwar','Director','Sarwar Developers','We brought AMARC in as project managers after our first contractor lost eight months. They rebuilt the programme and clawed most of it back.',5,5);
INSERT INTO public.clients (name,sort_order) VALUES
('Meridian Holdings',1),('Zafar Textiles',2),('Aafiyat Health Network',3),('Lahore Development Authority',4),('Punjab Agro Foods',5),('Askari Commercial Group',6),('Habib Land',7),('Sarwar Developers',8),('Higher Education Department, Punjab',9),('Serena Hospitality Ventures',10);
INSERT INTO public.certifications (title,issuer,reference_no,description,issued_year,sort_order) VALUES
