INSERT INTO public.milestones (year,title,description,sort_order) VALUES
('2004','AMARC founded in Lahore','Started as a three-person design and supervision practice working on private residences in Gulberg and Model Town.',1),
('2008','First turnkey construction contract','Moved from supervision into self-performed construction with a 12,000 sq ft commercial building in Johar Town.',2),
('2012','PEC constructor licence upgraded','Licence category raised, allowing tender participation on public-sector work of unlimited value.',3),
('2015','Karachi regional office opened','Opened on Shahrah-e-Faisal to serve Sindh clients directly rather than from Lahore.',4),
('2018','First infrastructure contract with LDA','Awarded the Ravi Road carriageway and drainage widening, the firm entry into public infrastructure.',5),
('2021','ISO 9001 and ISO 45001 certification','Formalised the quality and safety management systems that had been in internal use since 2016.',6),
('2023','Gulberg Corporate Tower delivered','Fourteen-storey grade-A office tower handed over nine weeks ahead of contract.',7),
('2025','AMARC Vantage launched','The firm largest own-account development to date launched on Main Boulevard.',8);
INSERT INTO public.posts (slug,title,excerpt,body,author,category,read_minutes,published_at,tags) VALUES
('construction-cost-per-square-foot-pakistan-2026','What it actually costs to build per square foot in Pakistan (2026)','Grey structure, finishing and turnkey rates for Lahore, Karachi and Islamabad — with the assumptions written down so you can check them.','Ask five contractors for a per-square-foot rate and you will get five numbers, because nobody agrees on what is included. Here is our current position, stated with the assumptions.
INSERT INTO public.jobs (slug,title,department,location,employment_type,experience,summary,description,responsibilities,requirements,sort_order) VALUES
('site-engineer-lahore','Site Engineer','Construction','Lahore','Full time','3–6 years','Site engineer for an active high-rise commercial project in Gulberg.','We are looking for a site engineer to join the delivery team on an active commercial project in Lahore. You will report to the project manager and be responsible for setting out, quality control and daily progress reporting.','["Setting out and level control","Daily progress reporting and photographic record","Material inspection and QA/QC documentation","Coordination with subcontractors and consultants","Enforcement of site HSE requirements"]'::jsonb,'["B.Sc. Civil Engineering from an HEC-recognised university","PEC registration","3–6 years of building construction experience","Working knowledge of AutoCAD and MS Project","Willingness to be site-based six days a week"]'::jsonb,1),
('structural-design-engineer','Structural Design Engineer','Engineering','Lahore','Full time','2–5 years','RCC and steel design engineer for the in-house structural team.','Join the structural team designing RCC and steel frames for buildings up to twenty storeys. You will work in ETABS and SAFE and be mentored toward stamping authority.','["Structural analysis and modelling in ETABS and SAFE","Member design to BCP and ACI","Reinforcement detailing and bar bending schedules","Coordination with the architecture studio","Site queries and RFI responses"]'::jsonb,'["B.Sc. or M.Sc. in Structural or Civil Engineering","PEC registration","Proficiency in ETABS, SAFE and AutoCAD","Understanding of BCP Seismic Provisions 2007"]'::jsonb,2),
('quantity-surveyor','Quantity Surveyor','Commercial','Karachi','Full time','4–8 years','Quantity surveyor for the Sindh regional commercial team.','Handle BOQ preparation, rate analysis, interim valuations and variation control across projects in Sindh.','["BOQ preparation and vetting","Rate analysis and subcontractor comparison","Interim payment applications and certification","Variation and claim documentation","Monthly cost reporting"]'::jsonb,'["B.Sc. Civil Engineering or B.Tech Quantity Surveying","4–8 years on building projects","Strong Excel and Candy or Primavera experience","Familiarity with FIDIC and PEC standard forms"]'::jsonb,3)
