INSERT INTO public.faqs (question,answer,category,sort_order) VALUES
('How do I get a price for my project?','Send us the plot size, location, approximate covered area and a rough brief through the contact form. We respond in writing within two working days with either a budget range or a list of what we need to price it properly. We do not give verbal per-square-foot quotes.','Getting started',1),
('Do you work on a fixed price or cost-plus basis?','Both. Private residential clients usually prefer a fixed price against a frozen BOQ. Institutional and industrial clients often prefer cost-plus with an agreed management fee and open-book accounting.','Commercial',2),
('What is included in your grey structure rate?','Excavation, foundation, RCC frame and slabs, blockwork, internal and external plaster, electrical and plumbing conduiting, roof treatment and waterproofing. It excludes all finishes, fixtures and fittings.','Commercial',3),
('How long does a 1-kanal house take?','Twelve to sixteen months from mobilisation to handover for a standard specification, assuming approvals are already in place. Higher-specification finishes and imported materials extend this.','Construction',4),
('Do you handle LDA, SBCA and CDA approvals?','Yes. Authority submission and approval tracking is included in our architectural service in Lahore, Karachi, Islamabad, Rawalpindi, Faisalabad and Multan.','Approvals',5),
('What warranty do you provide?','A twelve-month defects liability period from practical completion as standard, plus a ten-year structural warranty on projects where we carried out both design and construction.','After handover',6),
('Can I pay for a development in instalments?','Yes. Our developments run on 36 to 48 month instalment plans with a booking amount, monthly instalments and half-yearly balloon payments. The full schedule is published on each development page.','Real estate',7),
('Are buyer payments protected?','Payments on AMARC developments are held in a designated project account and buyer agreements carry a liquidated damages clause covering late handover.','Real estate',8);
